<template>
    <div class="backpack">
        <!--        <p>rank</p>-->
        <a-table :columns="columns" :data-source="rankList">
            <template #headerCell="{ column }">
                <template v-if="column.key === 'name'">
                    <span>
                        <smile-outlined />
                        Name
                    </span>
                </template>
            </template>
            <template #bodyCell="{ column, record, index, columnIndex }">
                <template v-if="column.key === 'ranking'">
                    <a> {{ index + 1 }} </a>
                </template>
                <template v-else-if="column.key === 'action'">
                    <a-button disabled type="primary">挑战</a-button>
                </template>
            </template>
        </a-table>
    </div>
</template>

<script>
import { reactive, toRefs, onMounted, ref } from "vue";
import rankApi from "@/assets/api/rankApi";
import { useI18n } from "vue-i18n";

export default {
    name: "Rank", // 排行
    setup() {
        const { t } = useI18n();
        const state = reactive({
            rankList: [],
            columns: [
                {
                    title: "排名",
                    dataIndex: "ranking",
                    key: "ranking"
                },
                {
                    title: "昵称",
                    dataIndex: "nickname",
                    key: "nickname"
                },
                {
                    title: "总灵气",
                    dataIndex: "attrTotal",
                    key: "attrTotal"
                },
                {
                    title: "基础灵气",
                    dataIndex: "attackpoint",
                    key: "attackpoint"
                },
                {
                    title: "额外灵气",
                    dataIndex: "extraTotal",
                    key: "extraTotal"
                },
                {
                    title: "积分",
                    key: "rankpoint"
                },
                {
                    title: "操作",
                    key: "action"
                }
            ]
        });

        onMounted(async () => {
            await getRankList();
        });

        const getRankList = async () => {
            let res = await rankApi.getList({});
            state.rankList = res.data;

            // 计算
            state.rankList.forEach(role => {
                let extraTotal = 0;
                role.backpacks.forEach((i) => {
                    const attr = JSON.parse(i.attr);
                    attr.forEach((j) => {
                        extraTotal += Number(j.desc);
                    });
                });
                role.extraTotal = extraTotal.toFixed(2);
                role.attrTotal = (Number(role.attackpoint) + Number(role.extraTotal)).toFixed(2);
            });

            // 排序
            state.rankList = state.rankList.sort((a, b) => {
                console.log(a.attrTotal, b.attrTotal);
                Number(b.attrTotal) - Number(a.attrTotal);
            });

            console.log(state.rankList);
        };

        return {
            ...toRefs(state)
        };
    }
};
</script>

<style lang="scss" scoped>
.backpack {
    padding: 20px;
}
</style>
